{"code": "
const r = await tools.pwsh({
  description: "Clean temp probes and recompute final hash",
  command: `$dir='D:\\lean\\tmp\\sheaf\\xif\\paper';
$targets = @('_S1850Probe0.lean','_S1850Probe1.lean','_S1850Probe2.lean','_S1850Probe3.lean','_S1850ImportTest.lean') | ForEach-Object { Join-Path $dir $_ };
foreach ($t in $targets) { if (Test-Path -LiteralPath $t) { Remove-Item -LiteralPath $t -Force; "removed $t" } };
$log='D:\\lean\\tmp\\s1850_build.out'; if (Test-Path -LiteralPath $log) { Remove-Item -LiteralPath $log -Force; "removed $log" };
"---remaining S1850 files---";
Get-ChildItem $dir -Filter '*S1850*' | Select-Object Name,Length | Format-Table -AutoSize;
Get-ChildItem 'D:\\lean\\.lake\\build\\lib\\lean\\tmp\\sheaf\\xif\\paper' -Filter '*S1850*' | Select-Object Name,Length | Format-Table -AutoSize;
"---final---";
$file=Join-Path $dir 'S1850RefuteS1756Actual.lean';
(Get-Content $file).Count; (Get-FileHash -Algorithm SHA256 $file).Hash`,
  workdir: "D:\\lean",
});
console.log(r.stdout.text);
", "description": "Delete probes and recompute final hash"}

